-- Kontrola príznaku is_sold (team_7) a poľa tickets_sold (team_5) v data lake (iba čítanie, SELECT).
-- Spustenie na serveri:
--   docker compose -f docker-compose.prod.yml exec -T postgres sh -c 'psql -U "$POSTGRES_USER" "$POSTGRES_DB"' < tools/lake_is_sold.sql > /tmp/out2.txt 2>&1
\pset pager off
\echo === A1 team_7 observations: ma ten isty zaznam (primarny kluc) viac hodnot is_sold?
with r as (select x from lake.message m, jsonb_array_elements(case when jsonb_typeof(m.payload_json->'rows')='array' then m.payload_json->'rows' else '[]'::jsonb end) x where m.team='team_7' and m.channel='sse' and m.source_ref->>'event'='snapshot' union all select m.payload_json->'record' from lake.message m where m.team='team_7' and m.channel='sse' and m.source_ref->>'event'='change' and m.payload_json->>'table' like '%observations'), k as (select x->>'source_table' t, coalesce(x->>'search_id', x->>'snapshot_id') || '|' || coalesce(x->>'offer_key', x->>'observation_key') key, x->>'is_sold' s from r where x ? 'is_sold') select t, count(*) zaznamov, count(*) filter (where n>1) s_viac_hodnotami from (select t, key, count(distinct s) n from k group by t, key) q group by t order by t;
\echo === A2 team_7 observations: prechody is_sold medzi po sebe prvymi zaznamami toho isteho letu (flight_key)
with r as (select x, m.received_at ra from lake.message m, jsonb_array_elements(case when jsonb_typeof(m.payload_json->'rows')='array' then m.payload_json->'rows' else '[]'::jsonb end) x where m.team='team_7' and m.channel='sse' and m.source_ref->>'event'='snapshot' union all select m.payload_json->'record', m.received_at from lake.message m where m.team='team_7' and m.channel='sse' and m.source_ref->>'event'='change' and m.payload_json->>'table' like '%observations'), k as (select x->>'source_table' t, coalesce(x->>'search_id', x->>'snapshot_id') || '|' || coalesce(x->>'offer_key', x->>'observation_key') key, x->>'flight_key' fk, (x->>'is_sold')::boolean s, ra from r where x ? 'is_sold' and x->>'flight_key' is not null), rec as (select t, fk, key, bool_or(s) s, min(ra) first_seen from k group by t, fk, key), w as (select t, fk, s, lag(s) over (partition by t, fk order by first_seen, key) prev from rec) select t, count(distinct fk) letov, count(*) zaznamov, count(*) filter (where prev is not null) dvojic, count(*) filter (where prev and not s) true_na_false, count(*) filter (where not prev and s) false_na_true from w group by t order by t;
\echo === A3 team_7 divadlo (REST): stabilita is_sold pre to iste id a prechody v case
with t as (select x from lake.message m, jsonb_array_elements(case when jsonb_typeof(m.payload_json->'data')='array' then m.payload_json->'data' else '[]'::jsonb end) x where m.team='team_7' and m.channel='rest'), k as (select x->>'id' id, x->>'performance_id' pid, x->>'captured_at' cap, x->>'is_sold' s from t) select count(*) zaznamov, count(*) filter (where n>1) s_viac_hodnotami from (select id, count(distinct s) n from k group by id) q;
with t as (select x from lake.message m, jsonb_array_elements(case when jsonb_typeof(m.payload_json->'data')='array' then m.payload_json->'data' else '[]'::jsonb end) x where m.team='team_7' and m.channel='rest'), k as (select x->>'id' id, x->>'performance_id' pid, x->>'captured_at' cap, (x->>'is_sold')::boolean s from t), rec as (select id, pid, min(cap) cap, bool_or(s) s from k group by id, pid), w as (select pid, s, lag(s) over (partition by pid order by cap, id) prev from rec) select count(distinct pid) predstaveni, count(*) snimok, count(*) filter (where prev is not null) dvojic, count(*) filter (where prev and not s) true_na_false, count(*) filter (where not prev and s) false_na_true from w;
\echo === C team_5 S3 (vzorka 3 percenta objektov): sleduje tickets_sold jeden let v case rastuco?
with s as (select payload_json pj from lake.message tablesample system (3) where team='team_5' and channel='s3' and jsonb_typeof(payload_json)='array'), i as (select e->'metadata'->>'scraper_id' sc, e->'metadata'->>'scraped_at_utc' ts, e->'payload'->>'flight_number' fn, e->'payload'->>'departure_date' dd, e->'payload'->>'origin' o, e->'payload'->>'destination' d, e->'payload'->>'tickets_sold' sold from s, jsonb_array_elements(pj) e where e->'payload'->>'tickets_sold' ~ '^[0-9]+$'), w as (select sc, sold::int sold, lag(sold::int) over (partition by sc, fn, dd, o, d order by ts) prev from i) select sc, count(*) pozorovani, count(*) filter (where prev is not null) dvojic, count(*) filter (where sold>prev) rastie, count(*) filter (where sold<prev) klesa, count(*) filter (where sold=prev) rovnake, round(avg(sold),2) priemer, max(sold) maximum from w group by sc order by sc;
